#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const manifestPath = path.join(here, "n0-guard-census.json");
const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
const entries = new Map(manifest.entries.map((entry) => [entry.id, entry]));

function seed(id, replacement, counterexample, rejectCode, acceptCode = "VALIDATE_SPECIMEN_ACCEPTED") {
  const entry = entries.get(id);
  if (!entry) throw new Error(`seed anchor missing: ${id}`);
  entry.mutation = { kind: "replace-node", replacement, direction: "fail-open" };
  entry.counterexample = { id: counterexample, rejectCode, acceptCode };
}

function seedExpression(id, replacement, counterexample, rejectCode, acceptCode) {
  const entry = entries.get(id);
  if (!entry) throw new Error(`seed anchor missing: ${id}`);
  entry.mutation = { kind: "replace-expression", replacement, direction: "fail-open" };
  entry.counterexample = { id: counterexample, rejectCode, acceptCode };
}

function seedSanitize(id, replacement, counterexample, rejectCode, acceptCode = "HELPER_ACCEPTED") {
  const entry = entries.get(id);
  if (!entry) throw new Error(`seed anchor missing: ${id}`);
  entry.mutation = { kind: "replace-expression", replacement, direction: "fail-open-sanitize" };
  entry.counterexample = { id: counterexample, rejectCode, acceptCode };
}

